<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{$uid=(int)requireAuth()->id;$year=(int)($_GET['year']??date('Y'));if($year<2000||$year>2200)throw new InvalidArgumentException('Invalid year');$conn=db();requirePermission($conn,$uid,'reports.view');$s=$conn->prepare('SELECT * FROM erp_employer_declarations WHERE user_id=? AND declaration_year=?');$s->bind_param('ii',$uid,$year);$s->execute();$header=$s->get_result()->fetch_assoc();$s->close();$lines=[];if($header){$s=$conn->prepare('SELECT id,category,beneficiary_name,beneficiary_fiscal_id,gross_amount,withheld_amount,source_supplier_payment_id,notes,created_at FROM erp_employer_declaration_lines WHERE declaration_id=? AND user_id=? ORDER BY category,beneficiary_name,id');$s->bind_param('ii',$header['id'],$uid);$s->execute();$lines=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}jsonResponse(['success'=>true,'year'=>$year,'header'=>$header?:null,'lines'=>$lines,'direction_notice'=>'Customer withholding certificates received by the company are excluded from this outbound employer declaration.']);}catch(Throwable $e){reportFailureResponse($e,'Could not load the employer declaration.','EMPLOYER_DECLARATION_LOAD_FAILED');}
